effect.shader:

 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

      vec3 CA(sampler2D tex, vec2 uv)
      {
          float strength = xxa;
          // float strength = 0.01;
          float r = texture2DCv(tex, uv + vec2(0.0, strength)).r;
          float g = texture2DCv(tex, uv).g;
          float b = texture2DCv(tex, uv + vec2(0.0, -strength)).b;
          vec3 final = vec3(r,g,b);
          return final;
      }

      vec3 Sharpen(sampler2D tex, vec2 uv)
      {
          float strength = xxb;
          // float strength = 0.0075;
          vec3 tl = CA(tex, uv + vec2(-strength, strength)).rgb;
          vec3 tm = CA(tex, uv + vec2(0.0, strength)).rgb;
          vec3 tr = CA(tex, uv + vec2(strength, strength)).rgb;
          vec3 ml = CA(tex, uv + vec2(-strength, 0.0)).rgb;
          vec3 mr = CA(tex, uv + vec2(strength, 0.0)).rgb;
          vec3 bl = CA(tex, uv + vec2(-strength, -strength)).rgb;
          vec3 bm = CA(tex, uv + vec2(0.0, -strength)).rgb;
          vec3 br = CA(tex, uv + vec2(strength, -strength)).rgb;
          vec3 final = (tl+tm+tr+ml+mr+bl+bm+br)/8.0;
          final = mix(texture2DCv(tex, uv).rgb, final, -2.0);
          return final;
      }

      vec3 Blur(sampler2D tex, vec2 uv)
      {
          float strength = xxc;
          // float strength = 0.0025;
          vec3 tl = Sharpen(tex, uv + vec2(-strength, strength)).rgb;
          vec3 tm = Sharpen(tex, uv + vec2(0.0, strength)).rgb;
          vec3 tr = Sharpen(tex, uv + vec2(strength, strength)).rgb;
          vec3 ml = Sharpen(tex, uv + vec2(-strength, 0.0)).rgb;
          vec3 mr = Sharpen(tex, uv + vec2(strength, 0.0)).rgb;
          vec3 bl = Sharpen(tex, uv + vec2(-strength, -strength)).rgb;
          vec3 bm = Sharpen(tex, uv + vec2(0.0, -strength)).rgb;
          vec3 br = Sharpen(tex, uv + vec2(strength, -strength)).rgb;
          vec3 final = (tl+tm+tr+ml+mr+bl+bm+br)/8.0;
          return final;
      }

      vec2 DistortUV(vec2 uv)
      {
     float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;
          float offs = texture2DCv(noisexx.texture, vec2(iTime, uv.y * 0.5)).r;
          offs -= 0.5;
          offs *= 2.0;
          offs *= xxd;
          // offs *= 0.0025;
          uv.x += offs;
          return uv;
      }

      vec3 ColourCorrect(vec3 col)
      {
          col += 0.1;
          col = clamp(col, vec3(0.0), vec3(1.0));
          col = pow(col, vec3(0.8));
          col /= xxe;
          // col /= 1.5;
          col = clamp(col, vec3(0.0), vec3(1.0));
          return col;
      }

      vec3 Finalize(vec3 col, vec2 uv)
      {
     float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;
          float bars = texture2DCv(noisexx.texture, vec2(iTime, uv.y * 0.1)).g;
          col += vec3(bars) * vec3(0.05, 0.01, 0.005);
          float n = texture2DCv(noisexx.texture, uv * 0.45 + (iTime * texture2DCv(noisexx.texture, vec2(iTime)).r)).b;
          n *= 0.05;
          return (col * n) + col / 1.1;
      }

/////////////////////////
 void main ()
 {

     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec3 iMouse = vec3(0.5, 0.5, 0.5);
     float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;

     vec2 umefx;
     umefx = acScreenNorm; 
     // umefx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     // umefx.y*=acLayerSize.y/acLayerSize.x;

     // umefx /= scale;
     // umefx *= rot2m((0.0+angle)*0.0174533);
     // umefx += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;
     // vec2 scaleVec;
     // scaleVec = vec2(scale*stretch.x,scale*stretch.y);
     // umefx /= scaleVec;

     /////////////////////////

 	vec4 fragColor;

          vec2 uv = umefx;
          uv = DistortUV(uv);

          vec3 colour = Blur(inputImg.texture, uv);
          colour = ColourCorrect(colour);
          colour = Finalize(colour, uv);

          fragColor = vec4(colour, 1.0);

 	    vec4 factor = mix(texColorX,fragColor,1.0);
 	    // const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
         // float luminance = dot(fragColor.rgb, luminanceWeighting);
         // vec4 gradmap = mix(color1,color2,luminance)*fragColor.a;
 	    // if(GRADMAP) { factor = mix(texColorX,gradmap,1.0); }

 	    // vec4 xbuffer = texture2DCv(buff1.texture, acScreenNorm.st);

     vec4 resultfinal;
       if( blendMode==0 ) { resultfinal = (factor * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.)*(1.-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
         // resultfinal = min(factor, texColor) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
           // resultfinal = max(factor, texColor) * texColor.a; }
       else if( blendMode==3 ) { factor *= hardness; resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
 	// }
 }
